const cfg = $('Config').item.json;
const rows = $input.all().map(item => item.json).filter(Boolean);

function extractVideoId(row) {
  if (row.external_id && /^[A-Za-z0-9_-]{11}$/.test(String(row.external_id))) return String(row.external_id);
  const url = String(row.external_url || row.response?.youtube_url || row.response?.url || row.response_json?.youtube_url || '');
  const patterns = [
    /youtu\.be\/([A-Za-z0-9_-]{11})/,
    /[?&]v=([A-Za-z0-9_-]{11})/,
    /\/shorts\/([A-Za-z0-9_-]{11})/,
    /\/embed\/([A-Za-z0-9_-]{11})/,
    /([A-Za-z0-9_-]{11})/
  ];
  for (const pattern of patterns) {
    const match = url.match(pattern);
    if (match) return match[1];
  }
  return null;
}

function isoDate(date) {
  return date.toISOString().slice(0, 10);
}

const now = new Date();
const end = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() - 1));
const minStart = new Date(end);
minStart.setUTCDate(minStart.getUTCDate() - Math.max(1, Number(cfg.lookback_days || 30)) + 1);

const jobs = [];
for (const row of rows) {
  const videoId = extractVideoId(row);
  if (!videoId || !row.id) continue;
  const isStudio = row.album_id != null;
  if (!isStudio && !row.episode_id) continue;
  const published = row.published_at ? new Date(row.published_at) : minStart;
  const publishedDate = Number.isNaN(published.getTime()) ? minStart : published;
  const start = new Date(Math.max(minStart.getTime(), Date.UTC(publishedDate.getUTCFullYear(), publishedDate.getUTCMonth(), publishedDate.getUTCDate())));
  const safeStart = start.getTime() > end.getTime() ? end : start;
  jobs.push({ json: {
    source_type: isStudio ? 'studio' : 'episode',
    episode_id: isStudio ? null : row.episode_id,
    publication_id: isStudio ? null : row.id,
    studio_album_id: isStudio ? row.album_id : null,
    studio_publication_id: isStudio ? row.id : null,
    youtube_video_id: videoId,
    external_url: row.external_url || `https://youtu.be/${videoId}`,
    start_date: isoDate(safeStart),
    end_date: isoDate(end)
  } });
}

return jobs;

const result = [];
const counts = { ok: 0, skipped: 0, unavailable: 0 };
const finite = value => { if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) throw new Error('Invalid metric value'); return value; };
const required = ['day','views','estimatedMinutesWatched','averageViewDuration','averageViewPercentage','subscribersGained','subscribersLost','likes','comments','shares'];
for (const item of $input.all()) {
  const response = item.json;
  if (response.status === 'skipped' || response.status === 'unavailable') { counts[response.status]++; continue; }
  if (response.status !== 'ok') throw new Error('Unexpected account analytics response');
  counts.ok++;
  const job = response.job;
  if (!job?.youtube_account_id || !job.channel_id || !job.youtube_video_id) throw new Error('Missing verified account identity');
  const headers = response.analytics?.columnHeaders?.map(h => h.name);
  const rows = response.analytics?.rows;
  if (!Array.isArray(headers) || !Array.isArray(rows) || headers.length !== required.length || new Set(headers).size !== required.length || !required.every(name => headers.includes(name))) throw new Error('Malformed analytics report');
  for (const row of rows) {
    if (!Array.isArray(row) || row.length !== headers.length) throw new Error('Malformed analytics row');
    const values = Object.fromEntries(headers.map((name, index) => [name, row[index]]));
    if (!/^\d{4}-\d{2}-\d{2}$/.test(values.day) || values.day < job.start_date || values.day > job.end_date) throw new Error('Analytics date outside requested window');
    result.push({ json: {
      episode_id: job.episode_id, publication_id: job.publication_id,
      studio_album_id: job.studio_album_id, studio_publication_id: job.studio_publication_id,
      youtube_video_id: job.youtube_video_id, metric_date: values.day,
      views: finite(values.views), engaged_views: 0,
      estimated_minutes_watched: finite(values.estimatedMinutesWatched),
      average_view_duration: finite(values.averageViewDuration),
      average_view_percentage: finite(values.averageViewPercentage),
      likes: finite(values.likes), comments: finite(values.comments), shares: finite(values.shares),
      subscribers_gained: finite(values.subscribersGained), subscribers_lost: finite(values.subscribersLost),
      traffic_sources: {}, countries: {},
      raw: { analytics_row: row, public_statistics: response.statistics,
        youtube_account_id: job.youtube_account_id, channel_id: job.channel_id,
        external_url: job.external_url, sync_window: {start_date:job.start_date,end_date:job.end_date} },
      synced_at: new Date().toISOString()
    } });
  }
}
if (counts.skipped || counts.unavailable) console.warn('YouTube analytics coverage: ' + JSON.stringify(counts));
return result;

const rowsByKey = new Map();
for (const { json: row } of $input.all()) {
  if (!row?.youtube_video_id || !row?.metric_date) {
    throw new Error('Metric rows require youtube_video_id and metric_date');
  }
  const key = JSON.stringify([row.youtube_video_id, row.metric_date]);
  const first = rowsByKey.get(key);
  // Preserve first-insert provenance, but refresh all metrics from the last row.
  // Coalesce globally before chunking so a key never spans concurrent requests.
  rowsByKey.set(key, first ? {
    ...row,
    episode_id: first.episode_id,
    publication_id: first.publication_id,
    studio_album_id: first.studio_album_id,
    studio_publication_id: first.studio_publication_id,
  } : row);
}
const rows = [...rowsByKey.values()];
const chunkSize = 500;
const chunks = [];
for (let i = 0; i < rows.length; i += chunkSize) {
  chunks.push({ json: { rows: rows.slice(i, i + chunkSize) } });
}
return chunks;
